import{_ as l,H as a,f as t,i}from"./chunks/framework.BH2BK_3i.js";const E=JSON.parse('{"title":"直播专场（三） | 同步：共享内存和消息传递","description":"","frontmatter":{},"headers":[{"level":2,"title":"Part 1 并发问题分类","slug":"part-1-并发问题分类","link":"#part-1-并发问题分类","children":[{"level":3,"title":"Rust 并发问题及修复方法","slug":"rust-并发问题及修复方法","link":"#rust-并发问题及修复方法","children":[]}]},{"level":2,"title":"Part 2 共享内存","slug":"part-2-共享内存","link":"#part-2-共享内存","children":[{"level":3,"title":"Mutex 互斥锁","slug":"mutex-互斥锁","link":"#mutex-互斥锁","children":[]},{"level":3,"title":"RwLock 读写锁","slug":"rwlock-读写锁","link":"#rwlock-读写锁","children":[]},{"level":3,"title":"Once、OnceLock、LazyLock  执行一次","slug":"once、oncelock、lazylock-执行一次","link":"#once、oncelock、lazylock-执行一次","children":[]},{"level":3,"title":"Condvar 条件变量","slug":"condvar-条件变量","link":"#condvar-条件变量","children":[]},{"level":3,"title":"Barrier 屏障","slug":"barrier-屏障","link":"#barrier-屏障","children":[]},{"level":3,"title":"Semaphore 信号量","slug":"semaphore-信号量","link":"#semaphore-信号量","children":[]},{"level":3,"title":"WaitGroup","slug":"waitgroup","link":"#waitgroup","children":[]},{"level":3,"title":"CountdownLatch","slug":"countdownlatch","link":"#countdownlatch","children":[]}]},{"level":2,"title":"Part 3 消息传递","slug":"part-3-消息传递","link":"#part-3-消息传递","children":[{"level":3,"title":"mpsc 通道","slug":"mpsc-通道","link":"#mpsc-通道","children":[]},{"level":3,"title":"mpmc 通道","slug":"mpmc-通道","link":"#mpmc-通道","children":[]}]}],"relativePath":"Rust并发编程实战课/直播专场（三）｜同步：共享内存和消息传递.md","filePath":"Rust并发编程实战课/直播专场（三）｜同步：共享内存和消息传递.md","lastUpdated":1795563064000}'),r={name:"Rust并发编程实战课/直播专场（三）｜同步：共享内存和消息传递.md"};function n(o,e,p,c,s,u){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="直播专场-三-同步-共享内存和消息传递" tabindex="-1">直播专场（三） | 同步：共享内存和消息传递 <a class="header-anchor" href="#直播专场-三-同步-共享内存和消息传递" aria-label="Permalink to &quot;直播专场（三） | 同步：共享内存和消息传递&quot;">​</a></h1><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Rust%E5%B9%B6%E5%8F%91%E7%BC%96%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E7%259B%25B4%25E6%2592%25AD%25E4%25B8%2593%25E5%259C%25BA%25EF%25BC%2588%25E4%25B8%2589%25EF%25BC%2589/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Rust%E5%B9%B6%E5%8F%91%E7%BC%96%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E7%259B%25B4%25E6%2592%25AD%25E4%25B8%2593%25E5%259C%25BA%25EF%25BC%2588%25E4%25B8%2589%25EF%25BC%2589/1.png" alt=""></a></p><h2 id="part-1-并发问题分类" tabindex="-1">Part 1 并发问题分类 <a class="header-anchor" href="#part-1-并发问题分类" aria-label="Permalink to &quot;Part 1 并发问题分类&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Rust%E5%B9%B6%E5%8F%91%E7%BC%96%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E7%259B%25B4%25E6%2592%25AD%25E4%25B8%2593%25E5%259C%25BA%25EF%25BC%2588%25E4%25B8%2589%25EF%25BC%2589/2.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Rust%E5%B9%B6%E5%8F%91%E7%BC%96%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E7%259B%25B4%25E6%2592%25AD%25E4%25B8%2593%25E5%259C%25BA%25EF%25BC%2588%25E4%25B8%2589%25EF%25BC%2589/2.jpeg" alt=""></a></p><h3 id="rust-并发问题及修复方法" tabindex="-1">Rust 并发问题及修复方法 <a class="header-anchor" href="#rust-并发问题及修复方法" aria-label="Permalink to &quot;Rust 并发问题及修复方法&quot;">​</a></h3><p>Rust 的并发问题相对较少，但仍需重视者在研究知名开源项目时发现了 100 多个并发 bug。</p><p>论文《Understanding and Detecting Real-World Safetylsisues in Rust》将 Rust 并发问题分成了两类，阻塞与非阻塞。</p><p>阻塞：阻塞错误在某个或多个线程执行等待资源（阻塞操作）的操作时出现，但这些资源从未可用。</p><p>非阻塞：</p><ul><li><p>非阻塞错误是并发错误的一种，所有线程都可以完成执行，但结果是不希望的。</p></li><li><p>Rust 支持共享内存和消息传递这两种跨线程通信的机制。</p></li><li><p>错误的数据共享是传统编程语言中大多数非阻塞错误的根本原因。</p></li></ul><p>阻塞：</p><ul><li><p>59 个阻塞错误中有 55 个是由同步原语的操作引起的，如 Mutex 和 Condvar。</p></li><li><p>其余四个错误不是由原语操作引起的（一个仅在 Windows 平台上阻塞在 API 调用处，两个在忙循环中阻塞，一个在线程的 join() 处阻塞）。</p></li><li><p>对 Rust 的生命周期规则缺乏良好的理解是许多阻塞错误的常见原因。</p></li><li><p>大部分 Rust 阻塞错误（51/59）都是通过调整同步操作来修复的，包括添加新的操作、移除不必要的操作以及移动或更改现有操作。</p></li><li><p>Rust 特有的修复策略之一是调整 lock()（或 read(), write()）返回变量的生命周期，以改变隐式解锁的位置。</p></li></ul><p>非阻塞：</p><ul><li><p>在 41 个非阻塞错误中，有三个是由消息传递错误引起的，其余的所有错误都是由于未能保护共享资源引起的。</p></li><li><p>23 个非阻塞错误使用不安全代码共享数据，其中 19 个使用内部不安全函数来共享数据。</p></li><li><p>通过传递指向内存空间的原始指针来共享数据</p></li><li><p>15 个非阻塞错误会与安全代码共享数据，具体情况如下：</p></li><li><p>[保护互斥] 五个错误使用原子变量作为共享变量。</p></li><li><p>[保护互斥] 而另外十个错误则使用 Mutex（或 RwL。ock）包装共享数据。</p></li><li><p>[生命周期] 九个错误使用 Arc 包装共享数据</p></li><li><p>[生命周期] 而其他六个错误则使用全局变量作为共享变量。</p></li></ul><h2 id="part-2-共享内存" tabindex="-1">Part 2 共享内存 <a class="header-anchor" href="#part-2-共享内存" aria-label="Permalink to &quot;Part 2 共享内存&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Rust%E5%B9%B6%E5%8F%91%E7%BC%96%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E7%259B%25B4%25E6%2592%25AD%25E4%25B8%2593%25E5%259C%25BA%25EF%25BC%2588%25E4%25B8%2589%25EF%25BC%2589/3.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Rust%E5%B9%B6%E5%8F%91%E7%BC%96%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E7%259B%25B4%25E6%2592%25AD%25E4%25B8%2593%25E5%259C%25BA%25EF%25BC%2588%25E4%25B8%2589%25EF%25BC%2589/3.jpeg" alt=""></a></p><p>主要介绍了共享内存方式的并发原语（或者叫同步原语）。</p><h3 id="mutex-互斥锁" tabindex="-1">Mutex 互斥锁 <a class="header-anchor" href="#mutex-互斥锁" aria-label="Permalink to &quot;Mutex 互斥锁&quot;">​</a></h3><ul><li><p>Mutex: Rust 中的加锁机制设计用于保护数据访问，而不是代码片段</p></li><li><p>Arc&lt;​Mutex&gt;: 多线程访问</p></li><li><p>lock() 函数返回一个 LockGuard 对象，当 LockGuard 的生命周期结束时，锁会自动释放</p></li></ul><h3 id="rwlock-读写锁" tabindex="-1">RwLock 读写锁 <a class="header-anchor" href="#rwlock-读写锁" aria-label="Permalink to &quot;RwLock 读写锁&quot;">​</a></h3><ul><li><p>write 获取写锁</p></li><li><p>read 获得读锁</p></li><li><p>Arc&lt;​RwLock&gt;: 多线程访问</p></li><li><p>Guard 自动释放</p></li></ul><h3 id="once、oncelock、lazylock-执行一次" tabindex="-1">Once、OnceLock、LazyLock 执行一次 <a class="header-anchor" href="#once、oncelock、lazylock-执行一次" aria-label="Permalink to &quot;Once、OnceLock、LazyLock  执行一次&quot;">​</a></h3><ul><li><p>Once::call_once 执行初始化一次</p></li><li><p>OnceLock::get_or_init 获取值，如果还未初始化则初始化</p></li><li><p>LazyLock::force 强制求值， 也可以隐式求值</p></li><li><p>死锁：call_once 递归调用此 Once 的 call_once</p></li></ul><h3 id="condvar-条件变量" tabindex="-1">Condvar 条件变量 <a class="header-anchor" href="#condvar-条件变量" aria-label="Permalink to &quot;Condvar 条件变量&quot;">​</a></h3><p>它允许线程在满足特定条件之前进入休眠状态。当条件满足时，其他线程可以发出信号唤醒等待的线程。条件变量最怕的是没有线程唤醒它们。</p><p>十个错误中：</p><ul><li><p>八个错误中有一个线程在调用条件变量的 wait() 时被阻塞，而没有其他线程调用同一个条件变量的 notify_one() 或 notify_all()。</p></li><li><p>在另外两个错误中，一个线程在等待另一个线程释放锁，而另一个线程在等待第一个线程调用 notify_all()。</p></li></ul><h3 id="barrier-屏障" tabindex="-1">Barrier 屏障 <a class="header-anchor" href="#barrier-屏障" aria-label="Permalink to &quot;Barrier 屏障&quot;">​</a></h3><p>它允许一组线程或进程相互等待，直到所有成员都到达某个预定的点。</p><ul><li><p>到达屏障的线程或进程会被阻塞，直到所有其他成员也到达。</p></li><li><p>一旦所有成员都到达，它们才能同时继续执行。</p></li></ul><h3 id="semaphore-信号量" tabindex="-1">Semaphore 信号量 <a class="header-anchor" href="#semaphore-信号量" aria-label="Permalink to &quot;Semaphore 信号量&quot;">​</a></h3><p>它维护一个计数器，表示可用资源的数量。线程可以通过以下两种操作来使用信号量：</p><ul><li><p>acquire()（P 操作或 down 操作）：尝试获取一个许可。如果计数器大于 0，则计数器减 1，线程继续执行；否则，线程将被阻塞，直到有许可可用。</p></li><li><p>release()（V 操作或 up 操作）：释放一个许可，使计数器加 1。如果有等待的线程，则唤醒其中一个。</p></li></ul><p>信号量的核心在于对计数器的管理，通过限制计数器的值，可以控制同时访问共享资源的线程数量。</p><h3 id="waitgroup" tabindex="-1">WaitGroup <a class="header-anchor" href="#waitgroup" aria-label="Permalink to &quot;WaitGroup&quot;">​</a></h3><p>WaitGroup 是一种并发编程中的同步机制，它允许一个“父”线程等待一组其他线程完成它们的执行。你可以把它想象成一个计数器：</p><ul><li><p>Add（添加）： 当你启动一个新的需要被“等待”的线程时，你会增加计数器的值。</p></li><li><p>Done（完成）： 每个被启动的线程在完成其工作后，会减少计数器的值。</p></li><li><p>Wait（等待）： “父”线程会阻塞（暂停执行），直到计数器的值变为零，这表示所有被启动的线程都已完成。</p></li></ul><h3 id="countdownlatch" tabindex="-1">CountdownLatch <a class="header-anchor" href="#countdownlatch" aria-label="Permalink to &quot;CountdownLatch&quot;">​</a></h3><ul><li><p>“Latch” 是一种倒计时的计数器，可用于同步线程或协调任务。计数器的值在创建时被初始化。线程 / 任务可以在 latch 上阻塞 / 挂起，直到计数器的值递减到 0。</p></li><li><p>就像 C++ 20 中的 std::latch、Java 中的 java.util.concurrent.CountDownLatch 和concurrent-ruby 中的 Concurrent::CountDownLatch。</p></li></ul><h2 id="part-3-消息传递" tabindex="-1">Part 3 消息传递 <a class="header-anchor" href="#part-3-消息传递" aria-label="Permalink to &quot;Part 3 消息传递&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Rust%E5%B9%B6%E5%8F%91%E7%BC%96%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E7%259B%25B4%25E6%2592%25AD%25E4%25B8%2593%25E5%259C%25BA%25EF%25BC%2588%25E4%25B8%2589%25EF%25BC%2589/4.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Rust%E5%B9%B6%E5%8F%91%E7%BC%96%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E7%259B%25B4%25E6%2592%25AD%25E4%25B8%2593%25E5%259C%25BA%25EF%25BC%2588%25E4%25B8%2589%25EF%25BC%2589/4.jpeg" alt=""></a></p><h3 id="mpsc-通道" tabindex="-1">mpsc 通道 <a class="header-anchor" href="#mpsc-通道" aria-label="Permalink to &quot;mpsc 通道&quot;">​</a></h3><p>multiple producer, single consumer</p><p>三种通道</p><ul><li><p>channel() 函数用于创建一个异步的 mpsc 通道</p></li><li><p>sync_channel(buffer) 函数则用于创建一个同步、有缓冲的 mpsc 通道</p></li><li><p>当缓冲区大小设置为 0 时，同步通道会变成一个“会合通道”（rendezvous channel）</p></li><li><p>[error] 从空通道拉取数据会阻塞一个线程，直到另一个线程向通道发送数据。</p></li><li><p>[error]两个或多个线程在等待通道中的数据，但无法向等待通道数据的线程发送数据。</p></li><li><p>[error]一个线程持有锁并等待从通道接收数据，而另一个线程在获取锁时被阻塞且无法发送其数据。</p></li></ul><h3 id="mpmc-通道" tabindex="-1">mpmc 通道 <a class="header-anchor" href="#mpmc-通道" aria-label="Permalink to &quot;mpmc 通道&quot;">​</a></h3><p>multiple producer, multiple consumer</p><ul><li><p>三种通道</p></li><li><p>channel() 函数用于创建一个异步的 mpmc 通道</p></li><li><p>sync_channel(buffer) 函数则用于创建一个同步、有缓冲的 mpmc 通道</p></li><li><p>当缓冲区大小设置为 0 时，同步通道会变成一个“会合通道”（rendezvous channel）</p></li></ul>',48)])])}const d=l(r,[["render",n]]);export{E as __pageData,d as default};
